export function load_ace_mode() {
  // Tweaked from code generated by Gemini
  ace.define(
    "ace/mode/fork_join",
    [
      "require",
      "exports",
      "module",
      "ace/lib/oop",
      "ace/mode/text",
      "ace/mode/text_highlight_rules",
    ],
    function (require, exports, module) {
      "use strict";

      var oop = require("../lib/oop");
      var TextMode = require("./text").Mode;
      var TextHighlightRules =
        require("./text_highlight_rules").TextHighlightRules;

      // 1. Highlight Rules Definition
      var MinimalHighlightRules = function () {
        this.$rules = {
          start: [
            // Comments: Start with -- until the end of the line
            {
              token: "comment",
              regex: "--.*$",
            },
            // Labels: Matches any alphanumeric/underscore sequence followed by a colon (e.g., MyLabel: or L1:)
            {
                token : "entity.name.function", // A common scope for labels/function names
                regex : "[a-zA-Z0-9_]+:"
            },
            // Keywords: FORK, JOIN, QUIT, GOTO
            {
              token: "keyword",
              regex: "\\b([Ff][Oo][Rr][Kk]|[Jj][Oo][Ii][Nn]|[Qq][Uu][Ii][Tt]|[Gg][Oo][Tt][Oo])\\b",
            },
            // Numbers (integers and decimals)
            {
              token: "constant.numeric",
              regex: "\\b\\d+(\\.\\d+)?\\b",
            },
          ],
        };
      };
      oop.inherits(MinimalHighlightRules, TextHighlightRules);

      // 2. Mode Definition
      var Mode = function () {
        this.HighlightRules = MinimalHighlightRules;
        this.$behaviour = this.$defaultBehaviour;
      };
      oop.inherits(Mode, TextMode);

      (function () {
        this.id = "ace/mode/fork_join"; // Unique mode ID
      }).call(Mode.prototype);

      exports.Mode = Mode;
    }
  );
}
